//
// go test 的工作目录是包目录（inventory/），所以从当前目录逐级向上找，
// 直到找到一份配置；从仓库根或包目录跑起来因此读到同一份文件。
func thresholdsFile() string {
	dir, err := os.Getwd()
	if err != nil {
		return filepath.Join("config", "thresholds.json")
	}
	for {
		candidate := filepath.Join(dir, "config", "thresholds.json")
		if _, err := os.Stat(candidate); err == nil {
			return candidate
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return filepath.Join("config", "thresholds.json")
		}
		dir = parent
	}
}

// readThresholds 从 path 读每仓库阈值。文件不存在、读不出来、
// 或内容不是 JSON 对象时返回 ok=false，由调用方回退默认值。
func readThresholds(path string) (map[string]int, bool) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, false
	}
	thresholds := make(map[string]int)
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, false
	}
	return thresholds, true
}

// thresholdFrom 返回 warehouse 的阈值：thresholds 里配了就用自己的，否则默认。
func thresholdFrom(thresholds map[string]int, ok bool, warehouse string) int {
	if ok {
		if threshold, found := thresholds[warehouse]; found {
			return threshold
		}
	}
	return DefaultLowStockThreshold
}

// lowStock 用一份已读入的配置判断 warehouse 是否低库存（严格小于阈值）。
func lowStock(thresholds map[string]int, ok bool, warehouse string, quantity int) bool {
	return quantity < thresholdFrom(thresholds, ok, warehouse)
}

// lowStockThreshold 是 path 处配置下 warehouse 的阈值，仅供测试与内部复用。
func lowStockThreshold(path, warehouse string) int {
	thresholds, ok := readThresholds(path)
	return thresholdFrom(thresholds, ok, warehouse)
}

// LowStockThreshold 返回这个仓库的低库存阈值：在 config/thresholds.json
// 里配了就用自己的，否则用 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	return lowStockThreshold(thresholdsFile(), warehouse)
}

// IsLowStock 报告库存是否低于该仓库的阈值。
func IsLowStock(warehouse string, quantity int) bool {
	thresholds, ok := readThresholds(thresholdsFile())
	return lowStock(thresholds, ok, warehouse, quantity)
}

// lowStockWarehouses 用一份已读入的配置筛出低库存仓库：
// 数量升序，数量相同的按仓库名升序。
func lowStockWarehouses(stock map[string]int, thresholds map[string]int, ok bool) []string {
	low := make([]string, 0, len(stock))
	for warehouse, quantity := range stock {
		if lowStock(thresholds, ok, warehouse, quantity) {
			low = append(low, warehouse)
		}
	}
	sort.Slice(low, func(i, j int) bool {
		if stock[low[i]] != stock[low[j]] {
			return stock[low[i]] < stock[low[j]]
		}
		return low[i] < low[j]
	})
	return low
}

// LowStockWarehouses 返回 stock 里所有低库存的仓库：
// 数量升序，数量相同的按仓库名升序。
func LowStockWarehouses(stock map[string]int) []string {
	// 整批共用一次读入的配置快照，避免每个仓库各读一次文件。
	thresholds, ok := readThresholds(thresholdsFile())
	return lowStockWarehouses(stock, thresholds, ok)
}

// lowStockReport 用一份已读入的配置生成报告行，仅供测试与内部复用。
func lowStockReport(stock map[string]int, thresholds map[string]int, ok bool) []string {
	warehouses := lowStockWarehouses(stock, thresholds, ok)
	report := make([]string, 0, len(warehouses))
	for _, warehouse := range warehouses {
		report = append(report, fmt.Sprintf("%s=%d", warehouse, stock[warehouse]))
	}
	return report
}

// LowStockReport 返回低库存仓库的报告行，每条形如 "<仓库>=<数量>"，
// 顺序与 LowStockWarehouses 一致。
func LowStockReport(stock map[string]int) []string {
	thresholds, ok := readThresholds(thresholdsFile())
	return lowStockReport(stock, thresholds, ok)
}

