	if got := lowStockThreshold(path, "chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestThresholdFallback(t *testing.T) {
